const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  VerticalAlign, LevelFormat, PageNumber
} = require('docx');
const fs = require('fs');

const GOLD = "B8965A";
const DARK = "1A1A2E";
const LIGHT_GOLD_BG = "FAF5EC";
const MID_GOLD = "D4AF72";
const BODY_FONT = "Georgia";
const HEAD_FONT = "Arial";
const CONTENT_WIDTH = 9360;

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const thinGold = { style: BorderStyle.SINGLE, size: 4, color: GOLD };

function spacer(before = 0, after = 0) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before, after } });
}

function goldRule() {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 1 } },
    spacing: { before: 0, after: 200 }
  });
}

function sectionLabel(text) {
  return new Paragraph({
    children: [
      new TextRun({
        text: text.toUpperCase(),
        font: HEAD_FONT,
        size: 18,
        bold: true,
        color: GOLD,
        characterSpacing: 120,
      })
    ],
    spacing: { before: 280, after: 80 }
  });
}

function bodyText(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({
      text,
      font: BODY_FONT,
      size: opts.size || 22,
      color: opts.color || DARK,
      bold: opts.bold || false,
      italics: opts.italics || false,
    })],
    alignment: opts.alignment || AlignmentType.LEFT,
    spacing: { before: opts.before || 0, after: opts.after || 100 }
  });
}

// Two-column phase table
function phaseTable(phases) {
  const colW = CONTENT_WIDTH / 2;
  const rows = [];
  for (let i = 0; i < phases.length; i += 2) {
    const cells = [];
    for (let j = i; j < Math.min(i + 2, phases.length); j++) {
      const p = phases[j];
      cells.push(new TableCell({
        borders: noBorders,
        width: { size: colW - 80, type: WidthType.DXA },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        shading: { fill: LIGHT_GOLD_BG, type: ShadingType.CLEAR },
        verticalAlign: VerticalAlign.TOP,
        children: [
          new Paragraph({
            children: [new TextRun({ text: p.label.toUpperCase(), font: HEAD_FONT, size: 16, bold: true, color: GOLD, characterSpacing: 80 })],
            spacing: { before: 0, after: 60 }
          }),
          new Paragraph({
            children: [new TextRun({ text: p.title, font: HEAD_FONT, size: 22, bold: true, color: DARK })],
            spacing: { before: 0, after: 80 }
          }),
          new Paragraph({
            children: [new TextRun({ text: p.desc, font: BODY_FONT, size: 20, color: "444444" })],
            spacing: { before: 0, after: 0 }
          }),
        ]
      }));
      if (j < Math.min(i + 2, phases.length) - 1) {
        // spacer cell
        cells.push(new TableCell({
          borders: noBorders,
          width: { size: 160, type: WidthType.DXA },
          margins: { top: 0, bottom: 0, left: 0, right: 0 },
          children: [new Paragraph({ children: [new TextRun("")] })]
        }));
      }
    }
    // If odd number and last row has 1 item, add empty cell
    if (phases.length % 2 !== 0 && i === phases.length - 1) {
      cells.push(new TableCell({
        borders: noBorders,
        width: { size: colW, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun("")] })]
      }));
    }
    rows.push(new TableRow({ children: cells }));
    if (i + 2 < phases.length) {
      rows.push(new TableRow({
        children: [new TableCell({
          borders: noBorders,
          width: { size: CONTENT_WIDTH, type: WidthType.DXA },
          columnSpan: 3,
          children: [spacer(80, 0)]
        })]
      }));
    }
  }

  return new Table({
    width: { size: CONTENT_WIDTH, type: WidthType.DXA },
    columnWidths: [colW - 80, 160, colW - 80],
    borders: { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder, insideH: noBorder, insideV: noBorder },
    rows
  });
}

// What we install - 3 column grid
function installGrid(items) {
  const colW = Math.floor(CONTENT_WIDTH / 3);
  const rows = [];
  for (let i = 0; i < items.length; i += 3) {
    const cells = [];
    for (let j = i; j < Math.min(i + 3, items.length); j++) {
      cells.push(new TableCell({
        borders: { top: { style: BorderStyle.SINGLE, size: 4, color: GOLD }, bottom: noBorder, left: noBorder, right: noBorder },
        width: { size: colW, type: WidthType.DXA },
        margins: { top: 100, bottom: 80, left: 80, right: 80 },
        children: [
          new Paragraph({
            children: [new TextRun({ text: items[j], font: BODY_FONT, size: 20, color: DARK })],
            spacing: { before: 0, after: 0 }
          })
        ]
      }));
    }
    while (cells.length < 3) {
      cells.push(new TableCell({
        borders: noBorders,
        width: { size: colW, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun("")] })]
      }));
    }
    rows.push(new TableRow({ children: cells }));
  }
  return new Table({
    width: { size: CONTENT_WIDTH, type: WidthType.DXA },
    columnWidths: [colW, colW, colW],
    borders: { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder, insideH: noBorder, insideV: noBorder },
    rows
  });
}

const phases = [
  {
    label: "Step 01",
    title: "Revenue Leak Audit",
    desc: "We surface what is already slipping through the cracks: undertrained front desks, unconverted consults, stagnant clients, missing memberships, weak packages. Most owners find tens of thousands in recoverable revenue before a single new dollar is invested."
  },
  {
    label: "Step 02",
    title: "Market Blueprint",
    desc: "Before recommending any new service, spend, or expansion, we map the competitive landscape. You will know exactly who you are up against in your market and where the clearest opportunity lives."
  },
  {
    label: "Step 03",
    title: "Foundation Build",
    desc: "With the audit complete and the blueprint in hand, we install what is missing: membership infrastructure, package architecture, staff sales training, AI-powered follow-up, CRM, and a client experience designed to earn loyalty without discounting."
  },
  {
    label: "Step 04",
    title: "Growth and Partnership",
    desc: "Ongoing marketing, accountability, monthly check-ins, and new deliverables as the aesthetic space evolves. We grow alongside the business, not ahead of it."
  }
];

const installs = [
  "Membership Programs",
  "Package Architecture",
  "Staff Sales Training",
  "AI-Powered Follow-Up",
  "CRM Integration",
  "Partnership Strategy",
  "Reputation and Review Engine",
  "Intentional Marketing",
  "Lifetime Value Frameworks",
];

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: BODY_FONT, size: 22, color: DARK } }
    }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1260, bottom: 1080, left: 1260 }
      }
    },
    children: [

      // Header block: name + tagline
      new Paragraph({
        children: [
          new TextRun({ text: "THE LUXORA COLLECTIVE", font: HEAD_FONT, size: 36, bold: true, color: DARK, characterSpacing: 150 })
        ],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "theluxoracollective.co", font: HEAD_FONT, size: 18, color: GOLD, characterSpacing: 60 })
        ],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 200 }
      }),
      goldRule(),

      // Opening statement
      new Paragraph({
        children: [
          new TextRun({
            text: "You did not build your med spa to manage spreadsheets. You built it because you believed in what you could offer your clients. The Luxora Collective exists to make sure the business you are running actually reflects the vision that inspired you to start.",
            font: BODY_FONT,
            size: 23,
            color: DARK,
            italics: true,
          })
        ],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160, after: 200 }
      }),

      goldRule(),

      // Who we serve
      sectionLabel("Who We Serve"),
      bodyText(
        "We are a premium revenue growth partner for independent med spa owners generating $500K to $2M annually. Whether your goal is to build the spa of your dreams, scale to a second location, or position for acquisition, we help you get there with a foundation that is actually built to support it.",
        { after: 160 }
      ),

      // How it works
      sectionLabel("How It Works"),
      spacer(60, 0),
      phaseTable(phases),
      spacer(200, 0),

      // What we install
      sectionLabel("What We Install"),
      spacer(80, 0),
      installGrid(installs),
      spacer(200, 0),

      // Done with you
      sectionLabel("Done With You. By Design."),
      bodyText(
        "This is not a done-for-you service that creates dependency. We work alongside owners and their existing teams, transferring knowledge and capability at every step. By the time we are done, the owner understands why every system works, how to run it, and how to build on it without us.",
        { after: 80 }
      ),
      bodyText(
        "The goal is not a client who needs us forever. It is an owner who is more capable, more confident, and more in control of their business than they were before we met.",
        { after: 160, bold: false, italics: true }
      ),

      goldRule(),

      // Footer CTA
      new Paragraph({
        children: [
          new TextRun({ text: "Ready to see what your business is really worth? Let's start with the Revenue Leak Audit.", font: HEAD_FONT, size: 22, bold: true, color: DARK })
        ],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160, after: 80 }
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "theluxoracollective.co", font: HEAD_FONT, size: 20, color: GOLD, bold: true })
        ],
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 0 }
      }),

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/luxora_partner_onepager.docx", buffer);
  console.log("Done");
});

