      cells.push(new TableCell({borders:noBorders,width:{size:colW,type:WidthType.DXA},margins:{top:80,bottom:80,left:120,right:120},shading:{fill:'FAF5EC',type:ShadingType.CLEAR},verticalAlign:VerticalAlign.TOP,children:[
        new Paragraph({children:[new TextRun({text:p.label.toUpperCase()+' / '+p.title,font:HEAD_FONT,size:16,bold:true,color:GOLD})],spacing:{before:0,after:40}}),
        new Paragraph({children:[new TextRun({text:p.desc,font:BODY_FONT,size:16,color:'444444'})],spacing:{before:0,after:0}}),
      ]}));
      if(j<Math.min(i+2,phases.length)-1){
        cells.push(new TableCell({borders:noBorders,width:{size:gap,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun('')]})]}));
      }
    }
    rows.push(new TableRow({children:cells}));
    if(i+2<phases.length){
      rows.push(new TableRow({children:[new TableCell({borders:noBorders,width:{size:CONTENT_WIDTH,type:WidthType.DXA},columnSpan:3,children:[spacer(50,0)]})]}));
    }
  }
  return new Table({width:{size:CONTENT_WIDTH,type:WidthType.DXA},columnWidths:[colW,gap,colW],borders:{top:noBorder,bottom:noBorder,left:noBorder,right:noBorder,insideH:noBorder,insideV:noBorder},rows});
}

function installGrid(items){
  const colW=Math.floor(CONTENT_WIDTH/3);
  const rows=[];
  for(let i=0;i<items.length;i+=3){
    const cells=[];
    for(let j=i;j<Math.min(i+3,items.length);j++){
      cells.push(new TableCell({borders:{top:{style:BorderStyle.SINGLE,size:3,color:GOLD},bottom:noBorder,left:noBorder,right:noBorder},width:{size:colW,type:WidthType.DXA},margins:{top:60,bottom:50,left:60,right:60},children:[new Paragraph({children:[new TextRun({text:items[j],font:BODY_FONT,size:16,color:DARK})],spacing:{before:0,after:0}})]}));
    }
    while(cells.length<3){cells.push(new TableCell({borders:noBorders,width:{size:colW,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun('')]})]}));}
    rows.push(new TableRow({children:cells}));
  }
  return new Table({width:{size:CONTENT_WIDTH,type:WidthType.DXA},columnWidths:[colW,colW,colW],borders:{top:noBorder,bottom:noBorder,left:noBorder,right:noBorder,insideH:noBorder,insideV:noBorder},rows});
}

